@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=Rajdhani:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--ink:#eef3ed;--muted:#99a6a4;--orange:#f2a34b;--cyan:#68e0dc;--red:#ff665c;--panel:rgba(13,20,22,.8);font-family:'Rajdhani',sans-serif}*{box-sizing:border-box}html,body,#game{width:100%;height:100%;margin:0;overflow:hidden;background:#101719;color:var(--ink)}body{user-select:none}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 49%,transparent 42%,rgba(4,9,10,.18) 100%),linear-gradient(180deg,rgba(5,11,13,.4),transparent 25%,transparent 67%,rgba(4,8,9,.48)}.screen{position:absolute;inset:0;z-index:5}.hidden{display:none!important}.title-copy{position:absolute;left:8.2%;top:16%;width:min(520px,45vw);z-index:2}.eyebrow{font-size:12px;letter-spacing:2.2px;font-weight:700;color:#c5cfca;display:flex;align-items:center;gap:10px}.eyebrow i,.live-dot{width:7px;height:7px;background:var(--orange);border-radius:50%;box-shadow:0 0 12px var(--orange);display:inline-block}.title-copy h1{font:900 clamp(74px,10vw,144px)/.76 'Barlow Condensed',sans-serif;letter-spacing:-3px;margin:27px 0 14px;text-shadow:0 7px 30px #121819}.title-copy h1 span{color:var(--orange)}.subtitle{font:700 17px 'Rajdhani',sans-serif;letter-spacing:6px;color:#e3e7e1;margin:24px 0 12px}.intro{font:500 17px/1.48 'Rajdhani',sans-serif;color:#c1cac5;margin:0 0 26px}.primary-button{display:flex;align-items:center;justify-content:space-between;gap:56px;min-width:237px;height:54px;padding:0 18px;border:0;background:var(--orange);color:#171a18;font:800 16px 'Rajdhani',sans-serif;letter-spacing:1.6px;cursor:pointer;clip-path:polygon(0 0,calc(100% - 13px) 0,100% 13px,100% 100%,0 100%);transition:filter .15s,transform .15s}.primary-button:hover{filter:brightness(1.13);transform:translateY(-2px)}.primary-button b{font-size:23px}.best-record{margin-top:24px;font-size:12px;color:#abb4b0;letter-spacing:1.5px}.best-record strong{margin-left:12px;color:#f0f3ed;font-size:17px}.title-bottom{position:absolute;left:8.2%;bottom:5.7%;height:43px;display:flex;align-items:center;gap:22px;color:#aab4ae;font-size:10px;letter-spacing:1.3px}.title-bottom>span:first-child{color:#e2a35d;font-weight:700}.title-bottom>div{display:flex;align-items:center;gap:4px}.title-bottom kbd,.pause-hint kbd{font:700 11px 'Rajdhani';min-width:21px;text-align:center;padding:4px 5px;border:1px solid rgba(216,230,222,.24);color:#edf3ee;background:rgba(15,22,22,.7)}.title-bottom small{font-size:10px;margin-left:5px}.build-tag{margin-left:30px!important;color:#84918c!important}.title-stamp{position:absolute;right:9%;top:17%;font:900 94px/.72 'Barlow Condensed';color:rgba(244,164,76,.18);text-align:center;transform:rotate(8deg);border:2px solid rgba(244,164,76,.12);padding:16px 27px}.title-stamp small{font:700 12px 'Rajdhani';letter-spacing:4px}.hud{position:absolute;inset:0;z-index:2;pointer-events:none}.topbar{position:absolute;top:0;left:0;right:0;height:78px;background:linear-gradient(180deg,rgba(7,13,14,.91),rgba(7,13,14,.18));display:flex;align-items:center;padding:0 38px;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px}.brand-mark{width:34px;height:34px;border:1px solid var(--orange);color:var(--orange);display:grid;place-items:center;font:800 15px 'Barlow Condensed';transform:skew(-8deg)}.brand div{display:grid;line-height:1}.brand b{font:800 15px 'Barlow Condensed';letter-spacing:1.3px}.brand small{font-size:9px;color:#9daaa4;letter-spacing:1.5px;margin-top:5px}.mission{position:absolute;left:50%;transform:translateX(-50%);display:flex;gap:11px;align-items:center;font:700 12px 'Rajdhani';letter-spacing:1.8px;color:#d4dad5}.mission strong{font:700 19px 'Barlow Condensed';color:#fff;margin-left:8px;letter-spacing:1px}.live-dot{width:6px;height:6px}.top-right{display:flex;align-items:center;gap:27px}.kill-count{display:grid;text-align:right;line-height:1}.kill-count small{font-size:9px;letter-spacing:1.3px;color:#9ca8a3}.kill-count b{font:700 23px 'Barlow Condensed';color:#eff1ea;margin-top:3px}.icon-button{width:34px;height:34px;border:1px solid #53605c;color:#e8eee8;background:rgba(14,22,23,.5);font-size:15px;cursor:pointer;pointer-events:auto}.left-hud{position:absolute;top:103px;left:38px;width:255px;padding:13px 15px;background:linear-gradient(90deg,rgba(8,15,16,.87),rgba(8,15,16,.55));border-left:2px solid var(--orange);clip-path:polygon(0 0,100% 0,100% calc(100% - 13px),calc(100% - 13px) 100%,0 100%)}.pilot-card{display:flex;align-items:center;gap:10px;padding-bottom:13px;border-bottom:1px solid rgba(220,232,224,.13)}.pilot-avatar{width:32px;height:32px;color:var(--orange);font-size:22px;border:1px solid rgba(241,162,72,.5);display:grid;place-items:center}.pilot-card div:nth-child(2){display:grid;line-height:1.1}.pilot-card small,.weapon-chip small{font-size:9px;color:#a2ada7;letter-spacing:1.1px}.pilot-card b,.weapon-chip b{font:700 14px 'Rajdhani';letter-spacing:1px;margin-top:3px}.status-pill{font:700 8px 'Rajdhani';letter-spacing:.8px;color:#8ce3c3;border:1px solid rgba(106,218,175,.4);padding:3px 4px;margin-left:auto}.stat-block{margin-top:13px}.stat-label{display:flex;justify-content:space-between;align-items:center;font-size:10px;color:#b9c3bd;letter-spacing:1px}.stat-label b{color:#f2f4ee;font:600 12px 'Rajdhani';letter-spacing:.3px}.stat-label em{font-style:normal;color:var(--orange);margin-left:6px}.bar{height:5px;margin-top:6px;background:rgba(232,242,235,.16);overflow:hidden}.bar i{display:block;width:100%;height:100%;background:linear-gradient(90deg,#e85d46,#ffad61);box-shadow:0 0 12px #fb754c;transition:width .2s}.xp-bar i{background:linear-gradient(90deg,#54bab3,#8af0dd);box-shadow:0 0 10px #63d8ca}.weapon-chip{display:flex;align-items:center;gap:8px;margin-top:15px;padding-top:12px;border-top:1px solid rgba(220,232,224,.13)}.weapon-icon{font-size:22px;color:var(--cyan)}.weapon-chip div{display:grid;line-height:1.05}.weapon-chip b{font-size:12px}.ready-dot{height:6px;width:6px;border-radius:50%;background:#79e3bc;margin-left:auto;box-shadow:0 0 8px #79e3bc}.right-hud{position:absolute;right:38px;top:101px;width:175px}.radar-frame{padding:9px;background:rgba(9,16,17,.74);border-top:1px solid rgba(117,209,196,.48);clip-path:polygon(0 0,100% 0,100% calc(100% - 12px),calc(100% - 12px) 100%,0 100%)}.radar-label{display:flex;justify-content:space-between;font-size:9px;letter-spacing:1px;color:#b4c0ba}.radar-label i{font-style:normal;color:#81dfb7;font-size:8px}#radar{display:block;width:156px;height:156px;margin-top:5px}.radar-footer{display:flex;justify-content:space-between;font-size:8px;letter-spacing:.8px;color:#879690;margin-top:4px}.buff-list{display:flex;flex-direction:column;align-items:flex-end;gap:5px;margin-top:9px}.buff{background:rgba(9,17,18,.78);border-right:2px solid var(--cyan);padding:5px 8px;color:#b9eee1;font-size:10px;letter-spacing:.7px}.center-reticle{position:absolute;left:50%;top:50%;width:26px;height:26px;transform:translate(-50%,-50%);display:flex;align-items:center;justify-content:center;gap:5px;opacity:.72}.center-reticle i{width:5px;height:5px;border:1px solid var(--orange);transform:rotate(45deg)}.center-reticle b{width:3px;height:3px;background:#fff}.center-reticle span{position:absolute;top:18px;white-space:nowrap;font-size:8px;color:#ffe0a8;letter-spacing:1.3px}.bottom-hud{position:absolute;bottom:25px;left:38px;right:38px;display:flex;align-items:flex-end;justify-content:space-between}.objective,.ability{display:flex;align-items:center;gap:11px;background:rgba(8,15,16,.73);padding:9px 13px;min-height:49px}.objective{border-left:2px solid var(--orange)}.objective-icon{font-size:23px;color:var(--orange)}.objective div,.ability div{display:grid;line-height:1}.objective small,.ability small{font-size:9px;color:#98a69f;letter-spacing:1.3px}.objective b,.ability b{font:700 13px 'Rajdhani';letter-spacing:.8px;margin-top:5px}.ability{position:relative;width:235px;border:1px solid rgba(118,219,207,.23)}.ability-glyph{font-size:22px;color:var(--cyan)}.ability kbd{float:right;padding:2px 4px;border:1px solid #52615b;font:600 9px 'Rajdhani';margin-left:5px}.ability-meter{position:absolute;bottom:0;left:0;right:0;height:2px;background:#394742}.ability-meter i{display:block;height:100%;width:100%;background:var(--cyan);transition:width .12s}.toast{position:absolute;top:22%;left:50%;transform:translate(-50%,-8px);padding:8px 18px;background:rgba(9,16,17,.86);border-bottom:1px solid var(--orange);font:700 12px 'Rajdhani';letter-spacing:1.4px;color:#f4c27e;opacity:0;transition:.3s}.toast.show{opacity:1;transform:translate(-50%,0)}.modal{display:grid;place-items:center;background:rgba(6,11,12,.54);backdrop-filter:blur(4px)}.modal-card{width:min(480px,92vw);text-align:center;background:rgba(14,21,22,.94);border:1px solid rgba(198,216,205,.2);padding:42px 44px;box-shadow:0 24px 80px #040808}.modal-card .eyebrow,.upgrade-wrap>.eyebrow{justify-content:center;color:#e3a65c}.modal-card h2,.upgrade-wrap h2{font:900 62px/.92 'Barlow Condensed';margin:14px 0;color:#f0f3ec;letter-spacing:1px}.modal-card p{color:#abb7b0;font-size:16px;margin:12px 0 25px}.modal-card .primary-button{margin:auto;min-width:260px}.pause-hint{margin-top:22px;color:#85928c;font-size:10px;letter-spacing:1.6px}.pause-hint kbd{font-size:9px;padding:2px 5px}.upgrade-wrap{width:min(850px,94vw);text-align:center}.upgrade-wrap h2{margin-bottom:7px}.upgrade-wrap h2 span{color:var(--orange)}.upgrade-subtitle{margin:0 0 26px;color:#aab5ae}.upgrade-options{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.upgrade-card{background:rgba(18,28,29,.95);border:1px solid rgba(189,210,198,.2);text-align:left;padding:22px 20px;min-height:170px;cursor:pointer;transition:.18s;position:relative}.upgrade-card:hover{border-color:var(--orange);transform:translateY(-5px);background:#1b2828}.upgrade-card .mod-icon{font-size:25px;color:var(--orange)}.upgrade-card h3{margin:10px 0 6px;font:800 18px 'Barlow Condensed';letter-spacing:1px}.upgrade-card p{margin:0;color:#aebbb4;font-size:14px;line-height:1.35}.upgrade-card .pick{position:absolute;right:12px;top:12px;font-size:9px;letter-spacing:1px;color:#8b9b93}.run-stats{display:flex;justify-content:center;gap:48px;margin:20px auto 28px}.run-stats div{display:grid;gap:4px}.run-stats small{font-size:9px;letter-spacing:1px;color:#96a49d}.run-stats b{font:700 28px 'Barlow Condensed'}.loading{position:absolute;z-index:9;inset:0;display:flex;justify-content:center;align-items:center;gap:10px;background:#101719;color:#bfcac3;font-size:12px;letter-spacing:2px;transition:opacity .4s}.loader{width:13px;height:13px;border:1px solid #65746d;border-top-color:var(--orange);border-radius:50%;animation:spin .7s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:760px){.title-copy{left:7%;top:13%;width:75vw}.title-copy h1{font-size:86px}.title-stamp{right:7%;top:10%;font-size:62px;padding:12px 18px}.title-bottom{left:7%;right:5%;gap:9px;flex-wrap:wrap;bottom:3%}.title-bottom>div:nth-of-type(3),.title-bottom>div:nth-of-type(4),.build-tag{display:none}.left-hud{left:12px;top:82px;width:215px;padding:10px}.right-hud{right:12px;top:85px;width:142px}.radar-frame{padding:6px}.radar-label{font-size:7px}#radar{width:128px;height:128px}.bottom-hud{left:12px;right:12px;bottom:10px}.ability{width:190px;padding:7px}.objective{padding:7px}.objective b{font-size:10px}.topbar{height:62px;padding:0 12px}.mission{font-size:9px;letter-spacing:1px}.mission strong{font-size:15px}.brand b{font-size:12px}.brand small{font-size:7px}.top-right{gap:9px}.kill-count small{font-size:7px}.upgrade-options{grid-template-columns:1fr;gap:8px;max-height:62vh;overflow:auto}.upgrade-card{min-height:110px;padding:13px 16px}.upgrade-card h3{margin:5px 0}.upgrade-wrap h2{font-size:48px}.upgrade-card .mod-icon{float:left;margin-right:10px}.upgrade-card p{padding-right:14px}.modal-card{padding:32px 22px}.modal-card h2{font-size:47px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const $ = (id) => document.getElementById(id);
const canvas = $('world');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x9a7761);
scene.fog = new THREE.FogExp2(0x9a7761, 0.012);
const camera = new THREE.PerspectiveCamera(48, innerWidth / innerHeight, .1, 180);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.18;
scene.add(new THREE.HemisphereLight(0xc8d7dc, 0x4c3021, 2.0));
const sun = new THREE.DirectionalLight(0xffd0a0, 3.2);
sun.position.set(-14, 24, 10); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024); sun.shadow.camera.left = -34; sun.shadow.camera.right = 34; sun.shadow.camera.top = 34; sun.shadow.camera.bottom = -34; sun.shadow.bias = -.001;
scene.add(sun);
const fill = new THREE.DirectionalLight(0x5da2b5, 1.0); fill.position.set(12, 8, -14); scene.add(fill);
const mats = {
  ground: new THREE.MeshStandardMaterial({ color: 0x796149, roughness: .95 }),
  dark: new THREE.MeshStandardMaterial({ color: 0x172327, metalness: .72, roughness: .34 }),
  armor: new THREE.MeshStandardMaterial({ color: 0x354b50, metalness: .64, roughness: .38 }),
  light: new THREE.MeshStandardMaterial({ color: 0xc07b42, metalness: .55, roughness: .42 }),
  gold: new THREE.MeshStandardMaterial({ color: 0xf0a049, metalness: .46, roughness: .3 }),
  joint: new THREE.MeshStandardMaterial({ color: 0x101719, metalness: .7, roughness: .31 }),
  glow: new THREE.MeshStandardMaterial({ color: 0x73e2dd, emissive: 0x27c6cf, emissiveIntensity: 2.3, metalness: .1, roughness: .18 }),
  red: new THREE.MeshStandardMaterial({ color: 0xf15f4e, emissive: 0x801a0f, emissiveIntensity: .55, metalness: .3, roughness: .4 }),
  rock: new THREE.MeshStandardMaterial({ color: 0x59483d, roughness: 1 }),
  enemy: new THREE.MeshStandardMaterial({ color: 0x80614e, metalness: .4, roughness: .6 }),
  enemyDark: new THREE.MeshStandardMaterial({ color: 0x392f2a, metalness: .56, roughness: .45 }),
  enemyGlow: new THREE.MeshStandardMaterial({ color: 0xff694e, emissive: 0xff2914, emissiveIntensity: 2.2 })
};
const plane = new THREE.Mesh(new THREE.PlaneGeometry(240, 240), mats.ground);
plane.rotation.x = -Math.PI / 2; plane.position.y = -.12; plane.receiveShadow = true; scene.add(plane);
const grid = new THREE.GridHelper(180, 90, 0xd19a68, 0xb48b69);
grid.position.y = -.1; grid.material.transparent = true; grid.material.opacity = .12; scene.add(grid);
const arenaDeco = new THREE.Group(); scene.add(arenaDeco);
function addRock(x,z,scale, colorMaterial=mats.rock) {
  const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(1, 0), colorMaterial);
  rock.position.set(x, scale * .32, z); rock.scale.set(scale * (0.7 + Math.random()*.55), scale * (.55 + Math.random()*.8), scale * (0.65 + Math.random()*.7));
  rock.rotation.set(Math.random()*.4, Math.random()*Math.PI, Math.random()*.3); rock.castShadow = true; rock.receiveShadow = true; arenaDeco.add(rock);
}
for (let i=0;i<95;i++) { const a=Math.random()*Math.PI*2, r=18+Math.random()*65; addRock(Math.cos(a)*r, Math.sin(a)*r, .25+Math.random()*2.2); }
for (let i=0;i<28;i++) {
  const a=i/28*Math.PI*2, r=58+Math.random()*12, h=10+Math.random()*15;
  const peak=new THREE.Mesh(new THREE.ConeGeometry(5+Math.random()*6,h,5), new THREE.MeshStandardMaterial({color:i%2?0x695143:0x80604c,roughness:1}));
  peak.position.set(Math.cos(a)*r,h/2-2,Math.sin(a)*r); peak.rotation.y=Math.random()*Math.PI; peak.castShadow=true; arenaDeco.add(peak);
}
// A rusted warning pylon gives the arena a readable landmark.
const pylon = new THREE.Group(); pylon.position.set(-11,0,-13); scene.add(pylon);
const pylonStem = new THREE.Mesh(new THREE.CylinderGeometry(.13,.25,5,7),mats.dark); pylonStem.position.y=2.5; pylonStem.castShadow=true; pylon.add(pylonStem);
const pylonLight = new THREE.Mesh(new THREE.OctahedronGeometry(.42),mats.red); pylonLight.position.y=5.1; pylon.add(pylonLight);
const beaconBeam = new THREE.Mesh(new THREE.CylinderGeometry(.05,.4,7,10,1,true),new THREE.MeshBasicMaterial({color:0xff784d,transparent:true,opacity:.08,side:THREE.DoubleSide})); beaconBeam.position.y=2.4;pylon.add(beaconBeam);
const mech = new THREE.Group(); scene.add(mech);
function box(parent, material, size, pos, rotation=[0,0,0], bevel=0) {
  const geo = bevel ? new THREE.BoxGeometry(...size, 1, 1, 1) : new THREE.BoxGeometry(...size);
  const mesh = new THREE.Mesh(geo, material); mesh.position.set(...pos); mesh.rotation.set(...rotation); mesh.castShadow=true; mesh.receiveShadow=true; parent.add(mesh); return mesh;
}
function sphere(parent,material,r,pos,scale=[1,1,1],segments=12) {
  const mesh=new THREE.Mesh(new THREE.SphereGeometry(r,segments,Math.max(8,segments>>1)),material); mesh.position.set(...pos); mesh.scale.set(...scale); mesh.castShadow=true; parent.add(mesh); return mesh;
}
function cylinderBetween(parent,material,a,b,r1,r2=r1,segments=8) {
  const start=new THREE.Vector3(...a),end=new THREE.Vector3(...b),dir=end.clone().sub(start);
  const mesh=new THREE.Mesh(new THREE.CylinderGeometry(r2,r1,dir.length(),segments),material);
  mesh.position.copy(start.add(end).multiplyScalar(.5)); mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),dir.normalize()); mesh.castShadow=true; parent.add(mesh); return mesh;
}
// Angular quadruped frame: armored carapace, wolf-like sensor head and exposed pistons.
box(mech,mats.dark,[1.18,.72,2.1],[0,1.56,0],[0,0,0]);
box(mech,mats.armor,[1.36,.45,1.18],[0,1.79,-.08],[0,0,0]);
box(mech,mats.light,[1.38,.16,.72],[0,2.02,-.18]);
box(mech,mats.dark,[.82,.38,.9],[0,1.92,.88],[.12,0,0]);
box(mech,mats.armor,[.72,.36,.78],[0,2.13,1.17],[.12,0,0]);
// Jaw, ears, twin sensor eyes and forward-mounted autocannon.
box(mech,mats.dark,[.56,.23,.55],[0,1.9,1.57],[.12,0,0]);
box(mech,mats.light,[.2,.09,.13],[0,1.79,1.85]);
for(const side of [-1,1]){
  const ear=box(mech,mats.gold,[.16,.52,.2],[side*.31,2.39,1.1],[side*-.13,0,side*-.23]);
  box(mech,mats.glow,[.12,.1,.07],[side*.3,2.1,1.53]);
  box(mech,mats.dark,[.25,.25,.48],[side*.48,1.88,.75],[0,0,side*-.13]);
  cylinderBetween(mech,mats.dark,[side*.42,2.03,1.04],[side*.42,2.03,2.45],.09,.075,8);
  cylinderBetween(mech,mats.gold,[side*.42,2.03,2.42],[side*.42,2.03,2.77],.075,.05,8);
  sphere(mech,mats.glow,.11,[side*.39,2.11,1.56],[1,.65,.6]);
  // rear exhaust pods
  cylinderBetween(mech,mats.joint,[side*.52,1.9,-.74],[side*.57,1.9,-1.47],.24,.19,9);
  sphere(mech,mats.glow,.14,[side*.57,1.9,-1.49]);
}
box(mech,mats.light,[.8,.14,.35],[0,1.65,-.95],[0,0,0]);
const legs=[];
for(const side of [-1,1]) for(const fore of [-1,1]){
  const hipZ=fore?.66:-.69, hipX=side*.51;
  const leg=new THREE.Group(); leg.position.set(hipX,1.53,hipZ); mech.add(leg);
  sphere(leg,mats.joint,.3,[0,0,0],[1,.9,1]);
  const upperEnd=[side*.12,-.49,fore*.09];
  cylinderBetween(leg,mats.armor,[0,-.04,0],upperEnd,.22,.16,7);
  box(leg,mats.light,[.36,.42,.3],[side*.03,-.33,fore*.04],[.06,0,side*.08]);
  sphere(leg,mats.joint,.19,upperEnd);
  const foot=[side*.18,-1.12,fore*.12];
  cylinderBetween(leg,mats.dark,upperEnd,foot,.14,.12,7);
  box(leg,mats.armor,[.38,.2,.48],[foot[0],foot[1]-.06,foot[2]+fore*.05],[0,0,side*.05]);
  box(leg,mats.gold,[.18,.07,.2],[foot[0],foot[1]-.17,foot[2]+fore*.16]);
  legs.push({group:leg,phase:(side+1)*1.3+(fore>0?0:Math.PI),side,fore});
}
// Scout's combat glow, shadow disc and subtle ground reticle.
const shadowDisc=new THREE.Mesh(new THREE.CircleGeometry(1.42,32),new THREE.MeshBasicMaterial({color:0x101719,transparent:true,opacity:.35,depthWrite:false}));shadowDisc.rotation.x=-Math.PI/2;shadowDisc.position.y=.015;mech.add(shadowDisc);
const selectionRing=new THREE.Mesh(new THREE.RingGeometry(1.5,1.57,48),new THREE.MeshBasicMaterial({color:0x62d9d2,transparent:true,opacity:.42,side:THREE.DoubleSide}));selectionRing.rotation.x=-Math.PI/2;selectionRing.position.y=.025;mech.add(selectionRing);
const raycaster=new THREE.Raycaster(), groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0), aimPoint=new THREE.Vector3(0,0,8);
let pointerNdc=new THREE.Vector2(0,0), aimWorld=new THREE.Vector3();
