  const body= new THREE.Mesh(new THREE.IcosahedronGeometry(.66*scale,1),bodyMat);body.position.y=.9*scale;body.scale.set(1.05,.72,1.22);body.castShadow=true;root.add(body);
  box(root,darkMat,[.38*scale,.35*scale,.63*scale],[0,1.19*scale,.42*scale]);
  for(const s of [-1,1]){
    sphere(root,mats.enemyGlow,.12*scale,[s*.25*scale,1.22*scale,.72*scale],[1,.65,.6]);
    const legZs=boss?[-.55,.45]:[-.4,.4];
    for(const z of legZs){
      cylinderBetween(root,darkMat,[s*.42*scale,.82*scale,z*scale],[s*.57*scale,.16*scale,z*scale],.12*scale,.09*scale,6);
      box(root,darkMat,[.2*scale,.15*scale,.26*scale],[s*.57*scale,.1*scale,z*scale]);
    }
  }
  if(type==='brute'||boss){
    box(root,bodyMat,[1.55*scale,.24*scale,.66*scale],[0,.95*scale,-.25*scale]);
    for(const s of [-1,1]) cylinderBetween(root,bodyMat,[s*.62*scale,1.22*scale,.1*scale],[s*.9*scale,1.14*scale,.42*scale],.18*scale,.08*scale,7);
  } else {
    cylinderBetween(root,bodyMat,[0,1.08*scale,.5*scale],[0,1.08*scale,1.13*scale],.1*scale,.055*scale,7);
