  const barBase=new THREE.Mesh(new THREE.PlaneGeometry(1.1, .09),new THREE.MeshBasicMaterial({color:0x151817,transparent:true,opacity:.8,depthTest:false}));barBase.position.y=2.15*scale;root.add(barBase);
  const barFill=new THREE.Mesh(new THREE.PlaneGeometry(1.04,.045),new THREE.MeshBasicMaterial({color:boss?0xff594b:0xeca05e,depthTest:false}));barFill.position.set(0,2.15*scale,.006);root.add(barFill);
  enemyGroup.add(root);
  const stats=boss?{hp:48,max:48,speed:1.55,damage:16,r:1.7,xp:12}:{brute:type==='brute'?{hp:7,max:7,speed:1.15,damage:13,r:.9,xp:3}:{hp:3,max:3,speed:2.05,damage:7,r:.55,xp:1};
