function updateGame(dt){
 gameTime+=dt;spawnTimer-=dt;fireTimer-=dt;pulseCd=Math.max(0,pulseCd-dt);
 const forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0);
