 const move=new THREE.Vector3(side,0,-forward);if(move.lengthSq()>0){move.normalize();mech.position.addScaledVector(move,player.speed*dt);}
 mech.position.x=THREE.MathUtils.clamp(mech.position.x,-42,42);mech.position.z=THREE.MathUtils.clamp(mech.position.z,-42,42);
 raycaster.setFromCamera(pointerNdc,camera);raycaster.ray.intersectPlane(groundPlane,aimWorld);
 if(aimWorld.distanceToSquared(mech.position)<.2)aimWorld.z+=1;
 mech.rotation.y=Math.atan2(aimWorld.x-mech.position.x,aimWorld.z-mech.position.z);
 legs.forEach((leg,i)=>{const moving=move.lengthSq()>.01;leg.group.rotation.x=moving?Math.sin(gameTime*9+leg.phase)*.38:Math.sin(gameTime*2+leg.phase)*.025;leg.group.rotation.z=moving?Math.cos(gameTime*9+leg.phase)*.045:0;});
 mech.position.y=Math.sin(gameTime*8)*.035*(move.lengthSq()>.01?1:.4);
