let state='title',keys={},gameTime=0,spawnTimer=0,fireTimer=0,pulseCd=0,kills=0,xp=0,level=1,xpNeed=8,shake=0,toastTimer=0;
let player={hp:100,maxHp:100,damage:2,fireRate:.29,speed:6.4,armor:0,magnet:3,pulse:18};
const upgradePool=[
 {name:'OVERCLOCKED COILS',icon:'ϟ',desc:'Increase arc-burst fire rate by 22%. More bolts, less machine.',apply:p=>p.fireRate*=.78},
 {name:'TUNGSTEN CORES',icon:'⬟',desc:'Weapon damage +1. Turn armored hostiles into scrap.',apply:p=>p.damage++},
