function startGame(){state='playing';gameTime=0;spawnTimer=.45;fireTimer=.15;pulseCd=0;kills=0;xp=0;level=1;xpNeed=8;scene.userData.bossSpawned=false;player={hp:100,maxHp:100,damage:2,fireRate:.29,speed:6.4,armor:0,magnet:3,pulse:18};for(const arr of [enemies,shots,pickups,effects]){for(const x of arr){const o=x.root||x.mesh||x.object;if(o?.parent)o.parent.remove(o)}arr.length=0}mech.position.set(0,0,0);mech.rotation.y=0;for(const id of ['title-screen','pause-screen','upgrade-screen','end-screen'])$(id).classList.add('hidden');$('hud').classList.remove('hidden');for(let i=0;i<5;i++){const a=i/5*Math.PI*2,e=makeEnemy();e.root.position.set(Math.cos(a)*13,0,Math.sin(a)*13)}toast('VANGUARD ONLINE // HOSTILES INBOUND');setHUD()}
function pauseGame(){if(state==='playing'){state='paused';$('pause-screen').classList.remove('hidden')}else if(state==='paused'){state='playing';$('pause-screen').classList.add('hidden')}}

