function pauseGame(){if(state==='playing'){state='paused';$('pause-screen').classList.remove('hidden')}else if(state==='paused'){state='playing';$('pause-screen').classList.add('hidden')}}
function damageEnemy(e,amount){e.hp-=amount;e.barFill.scale.x=Math.max(.02,e.hp/e.max);e.barFill.position.x=-(1-e.hp/e.max)*.52;if(e.hp<=0){const at=e.root.position.clone();burst(at.clone().add(new THREE.Vector3(0,.8,0)),e.boss?0xff7857:0xffbb70,e.boss?1.5:.7);enemyGroup.remove(e.root);enemies.splice(enemies.indexOf(e),1);kills++;spawnPickup(at,e.xp);if(Math.random()<.22)spawnPickup(at.clone().add(new THREE.Vector3((Math.random()-.5)*1.5,0,(Math.random()-.5)*1.5)));if(e.boss)toast('HEAVY SIGNATURE NEUTRALIZED')}}
function activatePulse(){if(state!=='playing'||pulseCd>0)return;pulseCd=player.pulse;shake=.35;const ring=new THREE.Mesh(new THREE.RingGeometry(.9,1.08,48),new THREE.MeshBasicMaterial({color:0x68fff0,transparent:true,opacity:.88,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.copy(mech.position);ring.position.y=.2;fxGroup.add(ring);effects.push({object:ring,life:.55,maxLife:.55,scale:12,pulse:true});for(const e of [...enemies])if(e.root.position.distanceTo(mech.position)<9)damageEnemy(e,player.damage*3+2);toast('OVERDRIVE PULSE // RELEASED')}
